-- Migration: Year 3 - Neurology MCQ Bank (COMPLETE: 1-355)
-- Based on Harrison's 22nd Ed, Step-Up to Medicine 5th Ed, and Pocket Medicine 7th Ed.
-- This file is IDEMPOTENT: It deletes existing Neurology MCQs before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'neurology' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Stroke and Cerebrovascular Disease

    -- SECTION 2: Epilepsy and Seizures
    (v_topic_id, '26: A "Simple Partial Seizure" (now Focal Aware) differs from a "Complex Partial Seizure" (now Focal Impaired Awareness) because:', '["It involves motor activity", "Consciousness is preserved", "It lasts longer", "None"]', 1, 'Awareness remains intact in simple focal seizures. (Harrison''s Ch. 418)'),
    (v_topic_id, '27: "Absence Seizures" (Petit Mal) are characterized by sudden staring spells and a characteristic ____ EEG pattern.', '["Spike and wave at 3 Hz", "Polyspikes", "Temporal spikes", "Flat line"]', 0, 'Common in children; usually no postictal state. (Step-Up)'),
    (v_topic_id, '28: What is the first-line treatment for Absence Seizures?', '["Phenytoin", "Ethosuximide", "Valproic Acid", "Carbamazepine"]', 1, 'Valproate is an alternative if tonic-clonic seizures also occur. (Pocket Medicine)'),
    (v_topic_id, '29: "Juvenile Myoclonic Epilepsy" (JME) classically presents with myoclonic jerks in the morning and is treated first-line with:', '["Lamotrigine", "Valproic Acid", "Phenobarbital", "None"]', 1, 'Broad-spectrum anti-epileptic. (Harrison''s Ch. 418)'),
    (v_topic_id, '30: Which anti-epileptic drug is known for causing "Gingival Hyperplasia" and hirsutism?', '["Levetiracetam", "Phenytoin", "Topiramate", "Valproate"]', 1, 'Also causes zero-order kinetics. (Step-Up)'),
    (v_topic_id, '31: "Carbamazepine" is first-line for Trigeminal Neuralgia but can cause which serious hematologic side effect?', '["Anemia", "Aplastic Anemia and Agranulocytosis", "Thrombocytopenia", "None"]', 1, 'Requires monitoring of CBC. (Pocket Medicine)'),
    (v_topic_id, '32: "Valproic Acid" should be avoided in pregnancy due to the high risk of:', '["Cleft lip", "Neural Tube Defects", "Limb defects", "Heart failure"]', 1, 'Interferes with folate metabolism. (Harrison''s Ch. 418)'),
    (v_topic_id, '33: "Status Epilepticus" is defined as a seizure lasting more than ____ minutes or recurrent seizures without return to baseline.', '["1", "5", "30", "60"]', 1, 'Clinical definition for starting emergent treatment. (Step-Up)'),
    (v_topic_id, '34: What is the FIRST-LINE emergent medication for Status Epilepticus?', '["Phenytoin", "Benzodiazepines (e.g., Lorazepam, Diazepam, Midazolam)", "Valproate", "Propofol"]', 1, 'Followed by a long-acting AED like Fosphenytoin. (Pocket Medicine)'),
    (v_topic_id, '35: "Todd''s Paralysis" refers to:', '["A permanent deficit", "Transient focal weakness following a seizure", "Weakness before a seizure", "None"]', 1, 'Usually resolves within 24 hours. (Harrison''s Ch. 418)'),
    (v_topic_id, '36: A "Generalized Tonic-Clonic" (Grand Mal) seizure includes a "tonic" phase of muscle contraction and a "clonic" phase of:', '["Sleep", "Rhythmic jerking", "Flaccidity", "None"]', 1, 'Followed by a postictal period of confusion. (Step-Up)'),
    (v_topic_id, '37: Which anti-epileptic is known for causing "weight loss" and "kidney stones"?', '["Valproate", "Topiramate", "Gabapentin", "None"]', 1, 'Also nicknamed "Dopamax" for cognitive slowing. (Pocket Medicine)'),
    (v_topic_id, '38: "Lamotrigine" requires slow titration to avoid which life-threatening skin reaction?', '["Hives", "Stevens-Johnson Syndrome (SJS) / TEN", "Psoriasis", "None"]', 1, 'Risk is increased if combined with Valproate. (Harrison''s Ch. 418)'),
    (v_topic_id, '39: "Psychogenic Non-Epileptic Seizures" (PNES) are characterized by long duration, side-to-side head shaking, and:', '["Elevated Prolactin", "Normal EEG during the event", "Tongue biting (side)", "None"]', 1, 'A form of conversion disorder. (Step-Up)'),
    (v_topic_id, '40: Seizures originating in the ____ lobe often present with olfactory or gustatory auras.', '["Frontal", "Temporal", "Parietal", "Occipital"]', 1, 'Common site for focal epilepsy. (Pocket Medicine)'),

    -- SECTION 3: Movement Disorders
    (v_topic_id, '41: The "Classic Triad" of Parkinson''s Disease includes resting tremor, bradykinesia, and:', '["Ataxia", "Rigidity (cogwheel)", "Chorea", "Seizures"]', 1, 'Postural instability is often added as a fourth feature. (Harrison''s Ch. 427)'),
    (v_topic_id, '42: The tremor in Parkinson''s Disease is typically described as:', '["Action tremor", "Pill-rolling tremor (resting)", "Intention tremor", "None"]', 1, 'Improves with purposeful movement. (Step-Up)'),
    (v_topic_id, '43: Parkinson''s Disease is caused by the loss of dopaminergic neurons in the:', '["Cerebellum", "Substantia Nigra pars compacta", "Striatum", "Thalamus"]', 1, 'Leads to depigmentation of the SN. (Pocket Medicine)'),
    (v_topic_id, '44: "Lewy Bodies" (intracellular aggregates of alpha-synuclein) are the hallmark of:', '["Alzheimer''s", "Parkinson''s and Lewy Body Dementia", "Huntington''s", "None"]', 1, 'Found in the SN in Parkinson''s. (Harrison''s Ch. 427)'),
    (v_topic_id, '45: What is the MOST effective medication for the motor symptoms of Parkinson''s?', '["Selegiline", "Levodopa/Carbidopa", "Pramipexole", "Amantadine"]', 1, 'Carbidopa prevents peripheral conversion of Levodopa. (Step-Up)'),
    (v_topic_id, '46: Long-term Levodopa use is associated with the development of:', '["Liver failure", "Motor fluctuations (On-Off) and Dyskinesias", "Kidney stones", "None"]', 1, 'Leads to "wearing-off" phenomenon. (Pocket Medicine)'),
    (v_topic_id, '47: "Multiple System Atrophy" (MSA) is a "Parkinson-Plus" syndrome characterized by prominent:', '["Dementia", "Autonomic dysfunction (orthostatic hypotension, incontinence)", "Vision loss", "None"]', 1, 'Shy-Drager syndrome is a variant. (Harrison''s Ch. 432)'),
    (v_topic_id, '48: "Progressive Supranuclear Palsy" (PSP) presents with parkinsonism and a characteristic deficit in:', '["Vertical gaze (downward)", "Horizontal gaze", "Hearing", "None"]', 0, 'Look for early frequent falls. (Step-Up)'),
    (v_topic_id, '49: "Huntington''s Disease" is an autosomal dominant disorder caused by an expanded ____ repeat.', '["CAG", "GAA", "CGG", "None"]', 0, 'Shows "Anticipation" (earlier onset in subsequent generations). (Pocket Medicine)'),
    (v_topic_id, '50: Huntington''s classically shows atrophy of which brain structure on MRI?', '["Hippocampus", "Caudate Nucleus", "Pons", "Occipital lobe"]', 1, 'Leads to "boxcar" ventricles. (Harrison''s Ch. 428)'),
    (v_topic_id, '51: "Essential Tremor" is typically a/an ____ tremor that improves with:', '["Resting; Sleep", "Action/Postural tremor; Alcohol", "Intention; Caffeine", "None"]', 1, 'Usually bilateral; treated with Propranolol or Primidone. (Step-Up)'),
    (v_topic_id, '52: "Wilson''s Disease" (copper metabolism defect) can present with a "Wing-beating tremor" and:', '["Kayser-Fleischer rings in the cornea", "Cataracts", "Rash", "None"]', 0, 'Requires evaluation of Ceruloplasmin levels. (Pocket Medicine)'),
    (v_topic_id, '53: "Tardive Dyskinesia" is a late complication of chronic use of:', '["Dopamine agonists", "Dopamine antagonists (Antipsychotics/Metoclopramide)", "Steroids", "NSAIDs"]', 1, 'Characterized by repetitive, involuntary movements of the mouth/tongue. (Harrison''s Ch. 430)'),
    (v_topic_id, '54: "Restless Legs Syndrome" (RLS) is often associated with which nutritional deficiency?', '["Vitamin B12", "Iron (Ferritin < 75)", "Calcium", "Vitamin D"]', 1, 'Symptoms improve with movement. (Step-Up)'),
    (v_topic_id, '55: "Sydenham Chorea" is a neurological manifestation of:', '["Lupus", "Acute Rheumatic Fever (Strep infection)", "Stroke", "None"]', 1, 'Involves molecular mimicry against the basal ganglia. (Pocket Medicine)'),

    -- SECTION 4: Demyelinating and Spinal Cord Disorders
    (v_topic_id, '56: "Multiple Sclerosis" (MS) is a chronic inflammatory demyelinating disease of the:', '["Peripheral Nervous System (PNS)", "Central Nervous System (CNS)", "Muscles", "None"]', 1, 'Characterized by lesions "separated in space and time." (Harrison''s Ch. 436)'),
    (v_topic_id, '57: "Optic Neuritis" (painful loss of vision) is a common initial presentation of MS, often showing a ____ on exam.', '["Cherry red spot", "Relative Afferent Pupillary Defect (RAPD)", "Cataract", "Glaucoma"]', 1, 'Also called Marcus Gunn pupil. (Step-Up)'),
    (v_topic_id, '58: "Internuclear Ophthalmoplegia" (INO), causing impaired adduction on lateral gaze, is due to a lesion in the:', '["Occipital lobe", "Medial Longitudinal Fasciculus (MLF)", "Optic Nerve", "Pons"]', 1, 'Highly suggestive of MS in a young patient. (Pocket Medicine)'),
    (v_topic_id, '59: "Lhermitte''s Sign" in MS is described as:', '["Pain on eye movement", "Electric-shock sensation down the spine with neck flexion", "Weakness on heat exposure", "None"]', 1, 'Indicates cervical cord involvement. (Harrison''s Ch. 436)'),
    (v_topic_id, '60: "Uhthoff''s Phenomenon" refers to the worsening of MS symptoms with:', '["Cold", "Heat/Exercise", "Sleep", "Darkness"]', 1, 'Due to impaired conduction in demyelinated axons. (Step-Up)'),
    (v_topic_id, '61: What is the MOST SENSITIVE imaging modality for diagnosing MS?', '["CT", "MRI with Gadolinium", "X-ray", "Ultrasound"]', 1, 'Shows "Dawson''s Fingers" (periventricular white matter lesions). (Pocket Medicine)'),
    (v_topic_id, '62: CSF analysis in MS classically shows:', '["High protein, low glucose", "Oligoclonal bands (IgG)", "Low WBC", "None"]', 1, 'Reflects intrathecal IgG synthesis. (Harrison''s Ch. 436)'),
    (v_topic_id, '63: What is the treatment of choice for an ACUTE MS flare?', '["Interferon-beta", "High-dose IV Corticosteroids", "Glatiramer acetate", "Cyclophosphamide"]', 1, 'Speeds recovery but doesn''t change long-term outcome. (Step-Up)'),
    (v_topic_id, '64: "Neuromyelitis Optica" (NMO or Devic Disease) differs from MS by the presence of:', '["Anti-Aquaporin 4 (AQP4) antibodies", "Oligoclonal bands", "Normal vision", "None"]', 0, 'Typically involves long segments of the spinal cord. (Pocket Medicine)'),
    (v_topic_id, '65: "Transverse Myelitis" presents with a clear ____ level of sensory and motor loss.', '["Ascending", "Dermatomal (horizontal)", "Patchy", "None"]', 1, 'Acute inflammation of the spinal cord. (Harrison''s Ch. 436)'),
    (v_topic_id, '66: "Brown-Séquard Syndrome" (spinal cord hemisection) causes ipsilateral motor loss and:', '["Ipsilateral pain/temp loss", "Contralateral pain/temp loss", "Bilateral loss", "None"]', 1, 'Crossed sensory findings due to spinothalamic tract decussation. (Step-Up)'),
    (v_topic_id, '67: "Syringomyelia" classically causes a "cape-like" distribution of loss of:', '["Vibration/Proprioception", "Pain and Temperature", "All sensation", "None"]', 1, 'Affects the crossing fibers of the spinothalamic tract in the anterior white commissure. (Pocket Medicine)'),
    (v_topic_id, '68: "Vitamin B12 Deficiency" causes "Subacute Combined Degeneration," affecting the dorsal columns and ____.', '["Spinothalamic tract", "Corticospinal tract", "Cerebellum", "None"]', 1, 'Leads to loss of vibration/position sense and spasticity. (Harrison''s Ch. 435)'),
    (v_topic_id, '69: "Tabes Dorsalis" (late Neurosyphilis) involves degeneration of the:', '["Ventral horns", "Dorsal columns", "Lateral columns", "None"]', 1, 'Leads to "sensory ataxia" and lightning pains. (Step-Up)'),
    (v_topic_id, '70: "Cauda Equina Syndrome" is a medical emergency characterized by saddle anesthesia, leg weakness, and:', '["Fever", "Bowel/bladder dysfunction", "Cough", "None"]', 1, 'Requires urgent surgical decompression. (Pocket Medicine)'),

    -- SECTION 5: Neuromuscular Disorders
    (v_topic_id, '71: "Myasthenia Gravis" (MG) is caused by autoantibodies against:', '["Calcium channels", "Post-synaptic Acetylcholine receptors (AChR)", "Muscle fibers", "None"]', 1, 'Characterized by fatigable muscle weakness. (Harrison''s Ch. 440)'),
    (v_topic_id, '72: Weakness in Myasthenia Gravis classically ____ with use and ____ with rest.', '["Improves; Worsens", "Worsens; Improves", "Does not change", "None"]', 1, 'Often involves the eyes (ptosis/diplopia). (Step-Up)'),
    (v_topic_id, '73: What is the first-line symptomatic treatment for Myasthenia Gravis?', '["Prednisone", "Pyridostigmine (Acetylcholinesterase inhibitor)", "Thymectomy", "IVIG"]', 1, 'Increases ACh availability at the NMJ. (Pocket Medicine)'),
    (v_topic_id, '74: "Lambert-Eaton Myasthenic Syndrome" (LEMS) is caused by antibodies against:', '["ACh receptors", "Pre-synaptic Voltage-gated calcium channels", "Potassium channels", "None"]', 1, 'Weakness IMPROVES with repetitive use. (Harrison''s Ch. 440)'),
    (v_topic_id, '75: LEMS is frequently a paraneoplastic syndrome associated with which cancer?', '["Squamous cell lung cancer", "Small Cell Lung Cancer", "Breast cancer", "None"]', 1, 'Screening with Chest CT is mandatory. (Step-Up)'),
    (v_topic_id, '76: "Amyotrophic Lateral Sclerosis" (ALS) is unique for having a combination of ____ and ____ signs.', '["Motor; Sensory", "Upper Motor Neuron (UMN); Lower Motor Neuron (LMN)", "Ataxic; Tremulous", "None"]', 1, 'Sensation and bowel/bladder function are usually preserved. (Pocket Medicine)'),
    (v_topic_id, '77: LMN signs include atrophy and ____ (fine muscle twitches).', '["Spasticity", "Fasciculations", "Hyperreflexia", "None"]', 1, 'Reflects muscle denervation. (Harrison''s Ch. 429)'),
    (v_topic_id, '78: UMN signs include hyperreflexia, spasticity, and a positive ____.', '["Hoffman''s", "Babinski sign (upgoing toe)", "Kernig''s", "None"]', 1, 'Indicates pyramidal tract involvement. (Step-Up)'),
    (v_topic_id, '79: "Guillain-Barré Syndrome" (GBS) is an acute demyelinating polyneuropathy that classically presents with ____ paralysis.', '["Descending", "Ascending", "Patchy", "None"]', 1, 'Often follows a Campylobacter jejuni infection. (Pocket Medicine)'),
    (v_topic_id, '80: CSF analysis in GBS shows "Albuminocytologic Dissociation," which means:', '["High protein with normal/low WBC", "Low protein with high WBC", "Normal everything", "None"]', 0, 'Critical diagnostic clue. (Harrison''s Ch. 439)'),
    (v_topic_id, '81: What is the treatment of choice for Guillain-Barré Syndrome?', '["Corticosteroids", "IVIG or Plasmapheresis", "Methotrexate", "None"]', 1, 'Steroids are NOT effective in GBS. (Step-Up)'),
    (v_topic_id, '82: "Miller Fisher Syndrome" is a variant of GBS characterized by ataxia, areflexia, and:', '["Hearing loss", "Ophthalmoplegia (weak eye muscles)", "Rash", "None"]', 1, 'Associated with anti-GQ1b antibodies. (Pocket Medicine)'),
    (v_topic_id, '83: "Charcot-Marie-Tooth" (CMT) disease is a hereditary neuropathy characterized by high arches (pes cavus) and:', '["Fat thighs", "Stork-leg deformity (distal muscle wasting)", "Big hands", "None"]', 1, 'Slowly progressive; multiple genetic types. (Harrison''s Ch. 438)'),
    (v_topic_id, '84: "Bell''s Palsy" (LMN facial nerve palsy) involves weakness of the entire half of the face, including the ____.', '["Mouth only", "Forehead", "Ear", "None"]', 1, 'UMN lesions (stroke) typically spare the forehead. (Step-Up)'),
    (v_topic_id, '85: What is the most common cause of "Peripheral Neuropathy" in the US?', '["B12 deficiency", "Diabetes Mellitus", "Alcohol", "Vasculitis"]', 1, 'Presents with a "stocking-glove" distribution. (Pocket Medicine)'),

    -- SECTION 6: Dementia and Cognitive Disorders
    (v_topic_id, '86: "Alzheimer''s Disease" is the most common cause of dementia, characterized pathologically by amyloid plaques and ____.', '["Lewy bodies", "Neurofibrillary tangles (tau protein)", "Pick bodies", "None"]', 1, 'Starts with short-term memory loss. (Harrison''s Ch. 423)'),
    (v_topic_id, '87: "Vascular Dementia" is characterized by a ____ decline in cognitive function.', '["Gradual", "Step-wise (often after strokes)", "Rapid (weeks)", "None"]', 1, 'Related to multi-infarct or small-vessel disease. (Step-Up)'),
    (v_topic_id, '88: "Dementia with Lewy Bodies" (DLB) presents with dementia, parkinsonism, and prominent:', '["Vertical gaze palsy", "Visual hallucinations and fluctuating alertness", "Aphasia", "None"]', 1, 'Highly sensitive to antipsychotic side effects. (Pocket Medicine)'),
    (v_topic_id, '89: "Frontotemporal Dementia" (Pick Disease) often presents early with changes in:', '["Memory", "Personality, behavior, and language", "Vision", "None"]', 1, 'Memory is often relatively preserved initially. (Harrison''s Ch. 424)'),
    (v_topic_id, '90: "Normal Pressure Hydrocephalus" (NPH) presents with the triad of "Wet, Wacky, and ____."', '["Wobbly (Ataxic gait)", "Weak", "Weary", "None"]', 0, 'Gait disturbance, urinary incontinence, and dementia. (Step-Up)'),
    (v_topic_id, '91: What is the treatment for Normal Pressure Hydrocephalus?', '["Steroids", "Ventriculoperitoneal (VP) Shunt", "Antibiotics", "None"]', 1, 'Gait often improves after a large-volume lumbar puncture (tap test). (Pocket Medicine)'),
    (v_topic_id, '92: "Creutzfeldt-Jakob Disease" (CJD) is a prion disease characterized by ____ and rapid dementia.', '["Myoclonus (startle-induced)", "Tremor", "Seizures", "None"]', 0, 'CSF shows 14-3-3 protein; MRI shows "hockey stick" sign in pulvinar. (Harrison''s Ch. 430)'),
    (v_topic_id, '93: "Wernicke Encephalopathy" is due to Thiamine (B1) deficiency and presents with ataxia, confusion, and:', '["Fever", "Ophthalmoplegia/Nystagmus", "Rash", "None"]', 1, 'Reversible; seen in alcoholics and malabsorption. (Step-Up)'),
    (v_topic_id, '94: If left untreated, Wernicke Encephalopathy can progress to the irreversible ____.', '["Alzheimer''s", "Korsakoff Syndrome (with confabulation)", "PML", "None"]', 1, 'Anterograde and retrograde amnesia. (Pocket Medicine)'),
    (v_topic_id, '95: "Donepezil" and "Rivastigmine" are used in Alzheimer''s and work by inhibiting:', '["Dopamine", "Cholinesterase", "NMDA receptors", "None"]', 1, 'Increases Acetylcholine levels. (Harrison''s Ch. 423)'),

    -- SECTION 7: Headache
    (v_topic_id, '96: "Migraine" headaches are typically unilateral, throbbing, and associated with:', '["Nasal congestion", "Nausea, vomiting, and photophobia", "Eye tearing", "None"]', 1, 'Often preceded by an "aura" (visual changes). (Step-Up)'),
    (v_topic_id, '97: What is the first-line medication for acute abortive therapy of moderate-to-severe Migraine?', '["Acetaminophen", "Triptans (e.g., Sumatriptan)", "Opioids", "Steroids"]', 1, '5-HT 1B/1D agonists; contraindicated in CAD. (Pocket Medicine)'),
    (v_topic_id, '98: "Cluster Headaches" are strictly unilateral, severe, periorbital, and occur in "clusters" with:', '["Nausea", "Autonomic symptoms (tearing, rhinorrhea, Horner''s)", "Fever", "None"]', 1, 'More common in men; "suicide headache." (Harrison''s Ch. 422)'),
    (v_topic_id, '99: What is the first-line abortive treatment for a Cluster Headache?', '["Aspirin", "100% Oxygen (high flow) or Sumatriptan", "Sleep", "Dark room"]', 1, 'Prophylaxis with Verapamil is common. (Step-Up)'),
    (v_topic_id, '100: "Tension-type Headache" is typically described as a ____ sensation.', '["Throbbing", "Band-like/Pressure", "Stabbing", "None"]', 1, 'Usually bilateral; no nausea or photophobia. (Pocket Medicine)');

    -- Batch 2: 101-200

    -- Batch 3: 201-355 (Rapid Fire and Special Topics)

END $$;

COMMIT;
