    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the MOST common cause of ischemic stroke overall?', '["Atrial Fibrillation", "Carotid Atherosclerosis", "Small-vessel (Lacunar) disease", "Cardioembolism"]', 1, 'Large-vessel atherosclerosis is the leading cause. (Harrison''s Ch. 419)'),
    (v_topic_id, '2: "Lacunar infarcts" are typically caused by lipohyalinosis of small penetrating arteries, strongly associated with:', '["Smoking", "Hypertension", "Atrial Fibrillation", "Hyperlipidemia"]', 1, 'HTN is the primary risk factor for lacunar strokes. (Step-Up)'),
    (v_topic_id, '3: A patient with sudden right-sided hemiparesis and aphasia most likely has an infarct in the territory of the:', '["Right Middle Cerebral Artery (MCA)", "Left Middle Cerebral Artery (MCA)", "Anterior Cerebral Artery (ACA)", "Posterior Cerebral Artery (PCA)"]', 1, 'Left MCA affects the dominant hemisphere (language) and right motor strip. (Pocket Medicine)'),
    (v_topic_id, '4: "Wernicke''s Aphasia" (fluent, nonsensical speech) is caused by a lesion in the ____ lobe.', '["Frontal", "Temporal (superior temporal gyrus)", "Parietal", "Occipital"]', 1, 'Sensory aphasia; patient is often unaware of the deficit. (Harrison''s Ch. 419)'),
    (v_topic_id, '5: "Broca''s Aphasia" (non-fluent, effortful speech) is caused by a lesion in the ____ lobe.', '["Frontal (inferior frontal gyrus)", "Temporal", "Parietal", "Occipital"]', 0, 'Motor aphasia; comprehension is typically preserved. (Step-Up)'),
    (v_topic_id, '6: Stroke in the territory of the Anterior Cerebral Artery (ACA) classically causes weakness and sensory loss primarily in the:', '["Face", "Arm", "Leg/Foot", "Hand"]', 2, 'ACA supplies the medial aspect of the motor and sensory strips. (Pocket Medicine)'),
    (v_topic_id, '7: "Wallenberg Syndrome" (Lateral Medullary Syndrome) is most commonly caused by occlusion of which artery?', '["Vertebral or PICA (Posterior Inferior Cerebellar Artery)", "Basilar", "AICA", "PCA"]', 0, 'Presents with ipsilateral Horner''s, ataxia, and crossed sensory loss. (Harrison''s Ch. 419)'),
    (v_topic_id, '8: A "Pure Motor Stroke" without sensory or cortical deficits is characteristic of a lacunar infarct in the:', '["Thalamus", "Internal Capsule (posterior limb)", "Midbrain", "Pons"]', 1, 'Small-vessel disease affecting the corticospinal tract. (Step-Up)'),
    (v_topic_id, '9: What is the time window for administering intravenous Alteplase (tPA) in acute ischemic stroke from symptom onset?', '["3 hours", "4.5 hours", "6 hours", "12 hours"]', 1, 'Extended to 4.5 hours in most eligible patients. (Pocket Medicine)'),
    (v_topic_id, '10: Mechanical Thrombectomy is generally considered for large vessel occlusions (LVO) up to ____ hours from last known normal.', '["6", "24", "48", "72"]', 1, 'Guided by advanced imaging (DAWN/DEFUSE-3 trials). (Harrison''s Ch. 419)'),
    (v_topic_id, '11: What is the first-line antihypertensive management for a patient with BP 200/110 in an acute ischemic stroke who is NOT a candidate for tPA?', '["Aggressive reduction to 120/80", "Permissive hypertension (unless BP > 220/120)", "Immediate IV Labetalol to 140/90", "None"]', 1, 'Avoid rapid reduction to maintain cerebral perfusion. (Step-Up)'),
    (v_topic_id, '12: "Thunderclap Headache" is the hallmark of which cerebrovascular emergency?', '["Ischemic Stroke", "Subarachnoid Hemorrhage (SAH)", "Migraine", "TIA"]', 1, '"Worst headache of my life." (Pocket Medicine)'),
    (v_topic_id, '13: What is the most common cause of non-traumatic Subarachnoid Hemorrhage?', '["AV Malformation", "Ruptured Saccular (Berry) Aneurysm", "Hypertension", "Amyloid Angiopathy"]', 1, 'Commonly located at the Circle of Willis junctions. (Harrison''s Ch. 419)'),
    (v_topic_id, '14: If a CT scan is negative for a suspected SAH, what is the next MANDATORY diagnostic step?', '["MRI Brain", "Lumbar Puncture (checking for Xanthochromia)", "Angiography", "None"]', 1, 'CT sensitivity drops over time. (Step-Up)'),
    (v_topic_id, '15: "Nimodipine" is administered after SAH primarily to prevent:', '["Re-bleeding", "Vasospasm and delayed cerebral ischemia", "Seizures", "Hydrocephalus"]', 1, 'Calcium channel blocker that improves outcomes. (Pocket Medicine)'),
    (v_topic_id, '16: "Epidural Hematoma" is classically caused by rupture of the Middle Meningeal Artery and shows a ____ shape on CT.', '["Crescent (Concave)", "Lens-shaped (Biconvex)", "Irregular", "None"]', 1, 'Often associated with a "lucid interval." (Harrison''s Ch. 419)'),
    (v_topic_id, '17: "Subdural Hematoma" is caused by rupture of bridging veins and shows a ____ shape on CT.', '["Lens-shaped", "Crescent-shaped", "Star-shaped", "None"]', 1, 'Common in the elderly and alcoholics following minor trauma. (Step-Up)'),
    (v_topic_id, '18: "Cerebral Amyloid Angiopathy" is a common cause of spontaneous intraparenchymal hemorrhage in the elderly, typically located in the:', '["Basal Ganglia", "Pons", "Lobes (Cortical)", "Cerebellum"]', 2, 'Different from hypertensive bleeds (deep). (Pocket Medicine)'),
    (v_topic_id, '19: Hypertensive intracerebral hemorrhages most commonly occur in the:', '["Basal Ganglia (Putamen)", "Frontal lobe", "Temporal lobe", "Medulla"]', 0, 'Due to rupture of Charcot-Bouchard aneurysms. (Harrison''s Ch. 419)'),
    (v_topic_id, '20: What is the CHADS2-VASc score used for in a patient with Atrial Fibrillation?', '["Stroke risk assessment and guiding anticoagulation", "Bleeding risk", "Severity of heart failure", "None"]', 0, 'Helps decide between Aspirin and Warfarin/DOAC. (Step-Up)'),
    (v_topic_id, '21: "Amaurosis Fugax" is a transient loss of vision in one eye, often described as a "shade coming down," and is a sign of:', '["Glaucoma", "Carotid Artery Stenosis", "Migraine", "Retinal detachment"]', 1, 'Transient Ischemic Attack of the retina. (Pocket Medicine)'),
    (v_topic_id, '22: A TIA is traditionally defined as symptoms resolving within 24 hours, but most TIAs actually last less than:', '["1 hour", "6 hours", "12 hours", "None"]', 0, 'Most resolve in minutes. (Harrison''s Ch. 419)'),
    (v_topic_id, '23: The "ABCD2" score is used to predict the risk of stroke after a:', '["TIA", "Seizure", "Head injury", "Faint"]', 0, 'Age, BP, Clinical features, Duration, Diabetes. (Step-Up)'),
    (v_topic_id, '24: A carotid endarterectomy (CEA) is generally recommended for symptomatic patients with stenosis of:', '["10-30%", "30-50%", ">70% (or 50-99% in select cases)", "100% (complete occlusion)"]', 2, 'CEA is not helpful for total occlusions. (Pocket Medicine)'),
    (v_topic_id, '25: What is the secondary prevention of choice for a patient with a non-cardioembolic ischemic stroke?', '["Warfarin", "Antiplatelet therapy (Aspirin, Clopidogrel, or Aspirin/Dipyridamole)", "Heparin", "None"]', 1, 'Dual antiplatelet therapy (DAPT) is often used for the first 21-90 days. (Harrison''s Ch. 419)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Idiopathic Intracranial Hypertension" (Pseudotumor Cerebri) is most common in obese young women and presents with headache and:', '["Fever", "Papilledema", "Hearing loss", "None"]', 1, 'Can lead to permanent vision loss if untreated. (Harrison''s Ch. 419)'),
    (v_topic_id, '102: What is the first-line medical treatment for Pseudotumor Cerebri?', '["Aspirin", "Acetazolamide", "Prednisone", "None"]', 1, 'Carbonic anhydrase inhibitor that reduces CSF production. (Step-Up)'),
    (v_topic_id, '103: "Giant Cell Arteritis" (Temporal Arteritis) must be considered in any patient over 50 with a new headache and:', '["High ESR", "Cough", "Diarrhea", "None"]', 0, 'Risk of irreversible blindness. (Pocket Medicine)'),
    (v_topic_id, '104: "Trigeminal Neuralgia" (Tic Douloureux) presents with brief, electric-shock-like pain in the ____ distribution.', '["Facial nerve", "Trigeminal nerve (V2/V3)", "Glossopharyngeal", "None"]', 1, 'Triggered by touch, chewing, or wind. (Harrison''s Ch. 434)'),
    (v_topic_id, '105: "Meniere''s Disease" presents with episodic vertigo, tinnitus, and:', '["Fever", "Low-frequency hearing loss", "Rash", "None"]', 1, 'Due to endolymphatic hydrops. (Step-Up)'),
    (v_topic_id, '106: "Benign Paroxysmal Positional Vertigo" (BPPV) is caused by otoliths in the semicircular canals and is diagnosed with the:', '["Epley maneuver", "Dix-Hallpike maneuver", "Romberg test", "None"]', 1, 'Treated with the Epley maneuver. (Pocket Medicine)'),
    (v_topic_id, '107: "Vitus Dance" is an old name for:', '["Epilepsy", "Sydenham Chorea", "Huntington''s", "None"]', 1, 'Associated with Rheumatic Fever. (Harrison''s Ch. 430)'),
    (v_topic_id, '108: "Locked-In Syndrome" (quadriplegia and loss of lower cranial nerves with preserved consciousness) is due to a lesion in the:', '["Medulla", "Ventral Pons", "Midbrain", "Cerebral cortex"]', 1, 'Usually from basilar artery occlusion or central pontine myelinolysis. (Step-Up)'),
    (v_topic_id, '109: "Central Pontine Myelinolysis" (Osmotic Demyelination) occurs when ____ is corrected too rapidly.', '["Hyperkalemia", "Hyponatremia", "Hypercalcemia", "None"]', 1, '"Low to high, your pons will die." (Pocket Medicine)'),
    (v_topic_id, '110: "Glioblastoma Multiforme" (GBM) is the most common primary malignant brain tumor in adults, classically showing a ____ pattern.', '["Whorled", "Butterfly (crossing corpus callosum)", "Cystic", "None"]', 1, 'Highly aggressive; grade IV astrocytoma. (Harrison''s Ch. 113)'),
    (v_topic_id, '111: "Meningiomas" are typically benign tumors that arise from the arachnoid cells and show ____ on histology.', '["Rosettes", "Psammoma bodies", "Fried egg cells", "None"]', 1, 'Usually attached to the dura. (Step-Up)'),
    (v_topic_id, '112: Which brain tumor is classically associated with "fried egg" appearance and calcifications?', '["Glioblastoma", "Oligodendroglioma", "Ependymoma", "None"]', 1, 'Often located in the frontal lobe. (Pocket Medicine)'),
    (v_topic_id, '113: "Schwannomas" (e.g., Acoustic Neuroma) classically occur at the cerebellopontine angle and affect which cranial nerve?', '["VII", "VIII", "V", "X"]', 1, 'Bilateral vestibular schwannomas are a hallmark of NF2. (Harrison''s Ch. 113)'),
    (v_topic_id, '114: "Medulloblastoma" is a highly malignant cerebellar tumor most common in:', '["Elderly", "Children", "Women", "None"]', 1, 'Can seed the neuraxis (drop metastasis). (Step-Up)'),
    (v_topic_id, '115: "Craniopharyngiomas" are benign tumors derived from Rathke''s pouch and can cause:', '["Blindness", "Bitemporal hemianopsia (compressing optic chiasm)", "Seizures", "None"]', 1, 'May have "machine-oil" fluid. (Pocket Medicine)'),
    (v_topic_id, '116: "Horner Syndrome" triad includes miosis, ptosis, and ____.', '["Sweating", "Anhidrosis (lack of sweating)", "Exophthalmos", "None"]', 1, 'Due to interruption of sympathetic fibers. (Harrison''s Ch. 31)'),
    (v_topic_id, '117: A "Pancoast Tumor" (lung apex) can cause Horner Syndrome by compressing the:', '["Brainstem", "Stellate ganglion / Sympathetic chain", "Optic nerve", "None"]', 1, 'High-yield clinical association. (Step-Up)'),
    (v_topic_id, '118: "Adie''s Tonic Pupil" is a benign condition where one pupil is ____ and reacts slowly to light.', '["Constricted", "Dilated", "Irregular", "None"]', 1, 'Due to ciliary ganglion damage. (Pocket Medicine)'),
    (v_topic_id, '119: "Argyll Robertson Pupil" (accommodates but doesn''t react to light) is a classic sign of:', '["MS", "Neurosyphilis", "Diabetes", "None"]', 1, '"Prostitute''s pupil." (Harrison''s Ch. 182)'),
    (v_topic_id, '120: "Papilledema" is swelling of the optic disc due to:', '["Infection", "Increased Intracranial Pressure", "Inflammation", "None"]', 1, 'Requires urgent neuroimaging. (Step-Up)'),
    (v_topic_id, '121: "Status Migrainosus" is a migraine that lasts for more than ____ hours.', '["24", "48", "72", "None"]', 2, 'Requires aggressive treatment, often in the ER. (Pocket Medicine)'),
    (v_topic_id, '122: Which medication class is used for Migraine prophylaxis?', '["Triptans", "Beta-blockers, Topiramate, or TCAs", "NSAIDS", "None"]', 1, 'Used when attacks are frequent. (Harrison''s Ch. 422)'),
    (v_topic_id, '123: "Restless Legs Syndrome" treatment often includes which drug class?', '["Dopamine antagonists", "Dopamine agonists (e.g., Pramipexole, Ropinirole)", "Steroids", "None"]', 1, 'Gabapentin is also used. (Step-Up)'),
    (v_topic_id, '124: "Narcolepsy" is characterized by daytime sleepiness, sleep paralysis, and ____ (sudden muscle weakness with emotion).', '["Seizures", "Cataplexy", "Apnea", "None"]', 1, 'Due to loss of Orexin/Hypocretin neurons. (Pocket Medicine)'),
    (v_topic_id, '125: "REM Sleep Behavior Disorder" (acting out dreams) is a strong predictor of future:', '["Alzheimer''s", "Alpha-synucleinopathies (Parkinson''s/LBD)", "Stroke", "None"]', 1, 'Occurs during REM sleep when muscle atonia is lost. (Harrison''s Ch. 35)'),
    (v_topic_id, '126: "Coma" is a state of deep unconsciousness where the patient cannot be aroused, unlike:', '["Brain death", "Vegetative state", "Stupor (aroused by vigorous stimuli)", "None"]', 2, 'Stupor is a less severe impairment of consciousness. (Step-Up)'),
    (v_topic_id, '127: "Brain Death" requires the absence of brainstem reflexes and a/an ____.', '["Flat EEG", "Apnea test", "Normal CT", "None"]', 1, 'Irreversible loss of all brain functions. (Pocket Medicine)'),
    (v_topic_id, '128: "Glasgow Coma Scale" (GCS) measures eye, verbal, and motor responses; a score of ____ or less indicates a severe coma.', '["15", "13", "8", "3"]', 2, '"GCS 8, intubate." (Harrison''s Ch. 301)'),
    (v_topic_id, '129: "Decerebrate posturing" (extension of arms/legs) indicates a lesion in the ____ and has a worse prognosis than decorticate.', '["Cerebral cortex", "Brainstem (below red nucleus)", "Thalamus", "None"]', 1, 'Decorticate (flexion) is above the red nucleus. (Step-Up)'),
    (v_topic_id, '130: "Cushing Triad" of increased ICP includes bradycardia, irregular respirations, and:', '["Hypotension", "Hypertension (widened pulse pressure)", "Tachycardia", "None"]', 1, 'A late sign of impending herniation. (Pocket Medicine)'),
    (v_topic_id, '131: "Uncal Herniation" compresses which cranial nerve first?', '["II", "III (causing a blown pupil)", "VI", "VII"]', 1, 'Leads to ipsilateral fixed, dilated pupil. (Harrison''s Ch. 301)'),
    (v_topic_id, '132: "Vasogenic edema" in the brain (e.g., from a tumor) is effectively treated with:', '["Diuretics", "Corticosteroids (Dexamethasone)", "Aspirin", "None"]', 1, 'Reduces capillary permeability. (Step-Up)'),
    (v_topic_id, '133: "Cytotoxic edema" in the brain (e.g., from stroke) does NOT respond to:', '["Mannitol", "Steroids", "Hypertonic saline", "None"]', 1, 'Intracellular swelling is not steroid-responsive. (Pocket Medicine)'),
    (v_topic_id, '134: "Subarachnoid Hemorrhage" Grading is often done using the ____ Scale.', '["Hunt and Hess", "Fisher", "Rankin", "NIHSS"]', 0, 'Fisher scale is for CT blood amount. (Harrison''s Ch. 419)'),
    (v_topic_id, '135: "Berry Aneurysms" are associated with which genetic condition?', '["Down Syndrome", "Autosomal Dominant Polycystic Kidney Disease (ADPKD)", "Cystic Fibrosis", "None"]', 1, 'Also Ehlers-Danlos and Marfan. (Step-Up)'),
    (v_topic_id, '136: "Moyamoya Disease" is a rare vascular disorder with "puff of smoke" collateral vessels on angiography, most common in:', '["Europeans", "East Asians (Children/Young Adults)", "Africans", "None"]', 1, 'Progressive occlusion of the internal carotid arteries. (Pocket Medicine)'),
    (v_topic_id, '137: "Transient Global Amnesia" (TGA) is a sudden episode of memory loss where the patient repeats:', '["Words", "The same questions over and over", "Movements", "None"]', 1, 'Usually lasts <24 hours and has a good prognosis. (Harrison''s Ch. 423)'),
    (v_topic_id, '138: "Capgras Syndrome" is the delusional belief that:', '["The patient is dead", "Familiar people have been replaced by imposters", "The patient is a god", "None"]', 1, 'Often seen in dementia or schizophrenia. (Step-Up)'),
    (v_topic_id, '139: "Anton Syndrome" is a state of cortical blindness where the patient:', '["Is depressed", "Denies they are blind (confabulation)", "Is deaf", "None"]', 1, 'Occurs with bilateral occipital lobe lesions. (Pocket Medicine)'),
    (v_topic_id, '140: "Gerstmann Syndrome" includes agraphia, acalculia, finger agnosia, and left-right disorientation, due to a lesion in the ____ parietal lobe.', '["Dominant (Left)", "Non-dominant (Right)", "Both", "None"]', 0, 'Affects the angular gyrus. (Harrison''s Ch. 27)'),
    (v_topic_id, '141: "Hemineglect" is most commonly seen with a lesion in the ____ parietal lobe.', '["Dominant (Left)", "Non-dominant (Right)", "Frontal", "None"]', 1, 'Patient ignores the left half of the world/body. (Step-Up)'),
    (v_topic_id, '142: "Prosopagnosia" is the inability to recognize faces, due to a lesion in the:', '["Fusiform gyrus", "Temporal pole", "Frontal eye fields", "None"]', 0, 'Occurs with bilateral inferior occipitotemporal lesions. (Pocket Medicine)'),
    (v_topic_id, '143: "Astereognosis" is the inability to identify an object by:', '["Sight", "Touch", "Sound", "None"]', 1, 'Indicates a parietal lobe lesion. (Harrison''s Ch. 27)'),
    (v_topic_id, '144: "Agraphesthesia" is the inability to recognize ____ traced on the skin.', '["Colors", "Letters or Numbers", "Textures", "None"]', 1, 'Test of cortical sensation. (Step-Up)'),
    (v_topic_id, '145: "Dysdiadochokinesia" (impaired rapid alternating movements) is a sign of ____ dysfunction.', '["Basal ganglia", "Cerebellar", "Frontal", "None"]', 1, 'Check with palm/back of hand tapping. (Pocket Medicine)'),
    (v_topic_id, '146: "Scanning Speech" (explosive, jerky speech) is seen in:', '["Parkinson''s", "Cerebellar disease (e.g., MS)", "Stroke", "None"]', 1, 'Lost rhythm of speech. (Harrison''s Ch. 433)'),
    (v_topic_id, '147: "Romberg Test" is positive when the patient sways with eyes ____, indicating a loss of ____.', '["Open; Vision", "Closed; Proprioception (Dorsal Columns)", "Open; Ataxia", "None"]', 1, 'Not a test of cerebellar function (which causes swaying even with eyes open). (Step-Up)'),
    (v_topic_id, '148: "Parinaud Syndrome" (Dorsal Midbrain Syndrome) presents with limited ____ gaze.', '["Downward", "Upward", "Lateral", "None"]', 1, 'Often due to a Pinealoma. (Pocket Medicine)'),
    (v_topic_id, '149: "Argyl Robertson Pupil" is often associated with "Tabes Dorsalis" and ____.', '["Charcot joints", "Hammer toes", "Ataxia", "None"]', 0, 'Loss of pain/vibration. (Harrison''s Ch. 182)'),
    (v_topic_id, '150: "Marcus Gunn Pupil" is diagnosed with the:', '["Cover test", "Swinging flashlight test", "Slit lamp", "None"]', 1, 'Light in affected eye causes paradoxically less constriction (appears to dilate). (Step-Up)'),
    (v_topic_id, '151: "Optic Atrophy" presents as a ____ optic disc on fundoscopy.', '["Red", "Pale/White", "Swollen", "None"]', 1, 'Sign of chronic nerve damage. (Pocket Medicine)'),
    (v_topic_id, '152: "Bitemporal Hemianopsia" is the hallmark of a lesion at the:', '["Optic nerve", "Optic chiasm (e.g., Pituitary tumor)", "Optic tract", "None"]', 1, 'Loss of the outer halves of the visual field. (Harrison''s Ch. 31)'),
    (v_topic_id, '153: "Right Homonymous Hemianopsia" is caused by a lesion in the:', '["Right optic tract", "Left optic tract or Left occipital lobe", "Optic chiasm", "None"]', 1, 'Deficit is on the side opposite the lesion. (Step-Up)'),
    (v_topic_id, '154: "Meyer''s Loop" (temporal lobe) lesion causes a:', '["Lower quadrantanopsia", "Upper quadrantanopsia (Pie in the sky)", "Total blindness", "None"]', 1, 'Supplies the inferior fibers of the radiation. (Pocket Medicine)'),
    (v_topic_id, '155: "Baum''s Loop" (parietal lobe) lesion causes a:', '["Upper quadrantanopsia", "Lower quadrantanopsia (Pie on the floor)", "Total blindness", "None"]', 1, 'Supplies the superior fibers of the radiation. (Harrison''s Ch. 31)'),
    (v_topic_id, '156: "Macular Sparing" in hemianopsia is often seen in PCA strokes due to dual blood supply from the:', '["ACA", "MCA", "PICA", "None"]', 1, 'MCA also supplies the occipital pole. (Step-Up)'),
    (v_topic_id, '157: "Foster Kennedy Syndrome" involves optic atrophy in one eye and ____ in the other, due to a frontal lobe tumor.', '["Blindness", "Papilledema", "Horner''s", "None"]', 1, 'Classic board finding. (Pocket Medicine)'),
    (v_topic_id, '158: "Nystagmus" that is purely vertical is usually a sign of a:', '["Peripheral lesion (inner ear)", "Central lesion (brainstem)", "Medication effect", "None"]', 1, 'Peripheral nystagmus is usually horizontal/torsional. (Harrison''s Ch. 31)'),
    (v_topic_id, '159: "Caloric testing" (COWS) refers to Cold Opposite, Warm Same for the direction of:', '["Slow phase", "Fast phase (nystagmus)", "Head tilt", "None"]', 1, 'Used to evaluate brainstem function in comatose patients. (Step-Up)'),
    (v_topic_id, '160: "Doll''s Eyes" (Oculocephalic reflex) should NOT be tested if ____ is suspected.', '["Stroke", "Cervical spine injury", "Meningitis", "None"]', 1, 'Requires rotating the head. (Pocket Medicine)'),
    (v_topic_id, '161: "Apraxia" is the inability to perform a ____ despite normal motor/sensory function.', '["Calculation", "Learned motor task (e.g., brushing hair)", "Speech", "None"]', 1, '"Ideomotor" is the most common type. (Harrison''s Ch. 27)'),
    (v_topic_id, '162: "Ataxia" refers to incoordination; "Sensory Ataxia" is specifically due to loss of:', '["Cerebellum", "Proprioception (Dorsal Columns)", "Motor strength", "None"]', 1, 'Worsens significantly when eyes are closed. (Step-Up)'),
    (v_topic_id, '163: "Spasticity" is velocity-____ resistance to passive stretch.', '["Independent", "Dependent", "Unrelated", "None"]', 1, 'Characteristic of UMN lesions. (Pocket Medicine)'),
    (v_topic_id, '164: "Rigidity" (like in Parkinson''s) is velocity-____.', '["Dependent", "Independent", "Variable", "None"]', 1, 'Resistance is constant throughout the range of motion. (Harrison''s Ch. 427)'),
    (v_topic_id, '165: "Myoclonus" is a sudden, brief, involuntary ____.', '["Muscle twitch", "Muscle contraction (jerk)", "Muscle relaxation", "None"]', 1, 'Asterixis (liver flap) is "negative myoclonus." (Step-Up)'),
    (v_topic_id, '166: "Chorea" is characterized by brief, irregular, ____ movements.', '["Rhythmic", "Dance-like/Flowing", "Sustained", "None"]', 1, 'Seen in Huntington''s and Sydenham''s. (Pocket Medicine)'),
    (v_topic_id, '167: "Athetosis" refers to slow, writhing, ____ movements, usually of the fingers.', '["Rapid", "Snakelike", "Jerky", "None"]', 1, 'Often seen with chorea (Choreoathetosis). (Harrison''s Ch. 427)'),
    (v_topic_id, '168: "Hemiballismus" is wild, flinging movements of half the body due to a lesion in the:', '["Caudate", "Subthalamic Nucleus", "Putamen", "None"]', 1, 'Usually from a lacunar stroke. (Step-Up)'),
    (v_topic_id, '169: "Dystonia" is characterized by sustained or repetitive ____.', '["Muscle twitches", "Muscle contractions causing abnormal postures", "Muscle weakness", "None"]', 1, 'Examples: Torticollis, Blepharospasm. (Pocket Medicine)'),
    (v_topic_id, '170: "Tremor" that is most prominent when reaching for an object (getting worse as it nears) is a/an ____ tremor.', '["Resting", "Intention (Cerebellar)", "Essential", "None"]', 1, 'Sign of cerebellar disease. (Harrison''s Ch. 433)'),
    (v_topic_id, '171: "Clonus" is a series of involuntary, rhythmic muscle contractions and relaxations, a sign of ____.', '["LMN lesion", "UMN lesion", "Muscular dystrophy", "None"]', 1, 'Commonly tested at the ankle. (Step-Up)'),
    (v_topic_id, '172: "Areflexia" or "Hyporeflexia" is a hallmark of ____.', '["Stroke", "LMN lesion (e.g., GBS, Peripheral Neuropathy)", "MS", "None"]', 1, 'Reflects a break in the reflex arc. (Pocket Medicine)'),
    (v_topic_id, '173: "Fasciculations" are visible only in ____ lesions.', '["UMN", "LMN (e.g., ALS, Polio)", "Brainstem", "None"]', 1, 'Sign of motor neuron irritation. (Harrison''s Ch. 429)'),
    (v_topic_id, '174: "Babinski Sign" (Great toe extension and fan of other toes) is normal in:', '["Adults", "Infants < 1 year old", "Coma", "None"]', 1, 'Indicates UMN damage in adults. (Step-Up)'),
    (v_topic_id, '175: "Cerebral Palsy" is a non-progressive permanent disorder of ____ and ____ development.', '["Memory", "Movement; Posture", "Speech", "None"]', 1, 'Often due to prenatal or perinatal brain injury. (Pocket Medicine)'),
    (v_topic_id, '176: "Spastic Diplegia" is the most common form of CP, often associated with:', '["Term birth", "Prematurity (Periventricular Leukomalacia)", "Old age", "None"]', 1, 'Affects the legs more than the arms. (Harrison''s Ch. 412)'),
    (v_topic_id, '177: "Tuberous Sclerosis" (TSC) is a genetic disorder presenting with seizures, intellectual disability, and ____.', '["Liver failure", "Ash-leaf spots and facial angiofibromas", "Hearing loss", "None"]', 1, 'Also subependymal nodules (tubers). (Step-Up)'),
    (v_topic_id, '178: "Neurofibromatosis Type 1" (NF1) is characterized by "Café-au-lait" spots, neurofibromas, and ____ in the eye.', '["Glaucoma", "Lisch nodules (iris hamartomas)", "Optic neuritis", "None"]', 1, 'Also associated with optic gliomas. (Pocket Medicine)'),
    (v_topic_id, '179: "Sturge-Weber Syndrome" presents with a "Port-wine stain" on the face and ____ in the brain.', '["Tumors", "Leptomeningeal angioma (with calcifications)", "Infarcts", "None"]', 1, '"Tram-track" calcifications on CT. (Harrison''s Ch. 438)'),
    (v_topic_id, '180: "Von Hippel-Lindau" (VHL) disease is associated with hemangioblastomas in the cerebellum/retina and ____.', '["Lung cancer", "Renal Cell Carcinoma", "Colon cancer", "None"]', 1, 'Autosomal dominant inheritance. (Step-Up)'),
    (v_topic_id, '181: "Friedreich Ataxia" is an autosomal recessive disorder (GAA repeat) presenting with ataxia, loss of vibration/position sense, and:', '["Liver failure", "Hypertrophic Cardiomyopathy and Diabetes", "Blindness", "None"]', 1, 'Presents in adolescence. (Pocket Medicine)'),
    (v_topic_id, '182: "Ataxia-Telangiectasia" presents with ataxia, spider angiomas (telangiectasias), and:', '["Low WBC", "Immunodeficiency and increased cancer risk", "High BP", "None"]', 1, 'Defect in DNA repair (ATM gene). (Harrison''s Ch. 433)'),
    (v_topic_id, '183: "Duchenne Muscular Dystrophy" (DMD) is an X-linked recessive disorder caused by a lack of ____.', '["Myosin", "Dystrophin", "Calcium", "None"]', 1, 'Presents with Gowers sign (using hands to "climb up" legs to stand). (Step-Up)'),
    (v_topic_id, '184: "Becker Muscular Dystrophy" is a ____ form of DMD with partially functional dystrophin.', '["More severe", "Milder", "Identical", "None"]', 1, 'Onset is later in childhood/adolescence. (Pocket Medicine)'),
    (v_topic_id, '185: "Myotonic Dystrophy" is an autosomal dominant disorder (CTG repeat) characterized by muscle wasting and ____ (difficulty releasing grip).', '["Atrophy", "Myotonia", "Weakness", "None"]', 1, 'Also presents with cataracts, balding, and arrhythmias. (Harrison''s Ch. 441)'),
    (v_topic_id, '186: "Periodic Paralysis" is a group of muscle disorders often triggered by changes in serum ____.', '["Sodium", "Potassium", "Calcium", "None"]', 1, 'Can be Hypokalemic or Hyperkalemic. (Step-Up)'),
    (v_topic_id, '187: "Malignant Hyperthermia" is a life-threatening reaction to inhaled anesthetics or succinylcholine, treated with:', '["Aspirin", "Dantrolene", "Penicillin", "None"]', 1, 'Due to RYR1 receptor defect causing massive calcium release. (Pocket Medicine)'),
    (v_topic_id, '188: "Neuroleptic Malignant Syndrome" (NMS) is a reaction to antipsychotics characterized by "Lead-pipe rigidity," fever, and:', '["Low BP", "Autonomic instability and altered mental status", "Hives", "None"]', 1, 'Treated with Dantrolene or Bromocriptine. (Harrison''s Ch. 430)'),
    (v_topic_id, '189: "Serotonin Syndrome" differs from NMS because it features ____ and hyperreflexia.', '["Rigidity", "Neuromuscular irritability (clonus, tremors)", "Bradycardia", "None"]', 1, 'Often follows SSRI/MAOI combination. (Step-Up)'),
    (v_topic_id, '190: "Transient Ischemic Attack" (TIA) in the vertebrobasilar territory often causes:', '["Aphasia", "Vertigo, diplopia, and ataxia", "Weakness on one side only", "None"]', 1, '"Drop attacks" may occur. (Pocket Medicine)'),
    (v_topic_id, '191: "Cerebellar hemorrhage" is a neurosurgical emergency; symptoms include sudden vertigo, vomiting, and ____.', '["Aphasia", "Inability to walk (truncal ataxia)", "Chest pain", "None"]', 1, 'May require urgent evacuation to prevent brainstem compression. (Harrison''s Ch. 419)'),
    (v_topic_id, '192: "Status Epilepticus" that is non-convulsive (NCSE) can only be diagnosed with:', '["CT", "EEG", "Blood test", "None"]', 1, 'Patient may just appear confused or "spaced out." (Step-Up)'),
    (v_topic_id, '193: "Focal Seizures" with "Jacksonian March" involve:', '["Aura", "Spread of motor activity up an extremity", "Loss of consciousness", "None"]', 1, 'Reflects sequential activation of the motor cortex. (Pocket Medicine)'),
    (v_topic_id, '194: "Generalized Seizures" always involve ____ at onset.', '["The whole body", "Loss of consciousness (and both hemispheres)", "Speech arrest", "None"]', 1, 'Includes Tonic-Clonic, Absence, and Myoclonic. (Harrison''s Ch. 418)'),
    (v_topic_id, '195: "Seizure" vs "Syncope": Syncope typically has a ____ recovery and lacks a ____ state.', '["Slow; Postictal", "Rapid; Postictal", "Long; Fever", "None"]', 1, 'Incontinence can occur in both. (Step-Up)'),
    (v_topic_id, '196: "Subclavian Steal Syndrome" occurs when a subclavian stenosis causes retrograde flow in the ____ artery during arm exercise.', '["Carotid", "Vertebral", "Radial", "None"]', 1, 'Causes vertebrobasilar insufficiency (dizziness). (Pocket Medicine)'),
    (v_topic_id, '197: "Meningitis" in neonates (<1 month) is most commonly caused by Group B Strep, E. coli, and ____.', '["Staph", "Listeria monocytogenes", "S. pneumoniae", "None"]', 1, 'Requires Ampicillin + Gentamicin. (Harrison''s Ch. 147)'),
    (v_topic_id, '198: "Dermatomyositis" has a high association with ____ (up to 25%).', '["Diabetes", "Malignancy", "Asthma", "None"]', 1, 'Screening for occult cancer is mandatory in adults. (Step-Up)'),
    (v_topic_id, '199: "Myasthenia Gravis" is frequently associated with abnormalities of the ____ gland.', '["Thyroid", "Thymus (Hyperplasia or Thymoma)", "Pituitary", "None"]', 1, 'Thymectomy often improves symptoms. (Pocket Medicine)'),
    (v_topic_id, '200: "Guillain-Barré" variant "Miller Fisher" is characterized by the presence of which antibody?', '["Anti-AChR", "Anti-GQ1b", "ANA", "None"]', 1, 'Strong diagnostic marker. (Harrison''s Ch. 439)');
